  "explanationSegs" : [ {
    "name" : "分析",
    "html" : "<p style=\"text-align:justify;word-break:break-word;\"><span style=\"font-family: 宋体;\">本题考查二次函数的图象与性质，熟练掌握二次函数的图象与性质是解题的关键．</span></p><p style=\"text-align:justify;word-break:break-word;\"><span style=\"font-family: 宋体;\">根据二次函数的图象与性质进行判断即可．</span></p>"
  }, {
    "name" : "详解",
    "html" : "<p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">解：观察图象得：抛物线开口向下，与</span><span style=\"font-style: italic;font-family: 'Times New Roman';\">y</span><span style=\"font-family: 宋体;\">轴交于正半轴，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/4bda2cbcdf2faee9e829618065a3e2ee.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∵对称轴是直线</span><img src=\"https://img.xkw.com/dksih/formula/9b384412acba251d87902ab928902f16.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/7091cbd3ca7ced4abaab38193733ed19.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/64d3a07e2fd5fbc45b6e5e6b0de45c17.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/16de2d7f06346a0fc6b5d6822e746237.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，故</span><span style=\"font-family: 'Times New Roman';\">①</span><span style=\"font-family: 宋体;\">正确；</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∵抛物线与</span><span style=\"font-style: italic;font-family: 'Times New Roman';\">x</span><span style=\"font-family: 宋体;\">轴的一个交点的横坐标</span><img src=\"https://img.xkw.com/dksih/formula/bb5ffa21fddc7c55d35f13435792b2d4.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，且对称轴是直线</span><img src=\"https://img.xkw.com/dksih/formula/9b384412acba251d87902ab928902f16.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴与</span><span style=\"font-style: italic;font-family: 'Times New Roman';\">x</span><span style=\"font-family: 宋体;\">轴的另一个交点的横坐标</span><img src=\"https://img.xkw.com/dksih/formula/3ae62acb0dfadef4340ede22968b665a.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴方程</span><img src=\"https://img.xkw.com/dksih/formula/4c3f3db6b7c682450309a6ccba5ac5a2.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">必有一个根大于</span><span style=\"font-family: 'Times New Roman';\">2</span><span style=\"font-family: 宋体;\">且小于</span><span style=\"font-family: 'Times New Roman';\">3</span><span style=\"font-family: 宋体;\">，故</span><span style=\"font-family: 'Times New Roman';\">②</span><span style=\"font-family: 宋体;\">正确；</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">当</span><img src=\"https://img.xkw.com/dksih/formula/99c6875d552e9fff3c7d655f3a59b166.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">时，</span><img src=\"https://img.xkw.com/dksih/formula/abedcf89f344f61b7bbd825fcc97f0c4.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/a848ad6eec86414350149acf4841c6f0.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∵</span><img src=\"https://img.xkw.com/dksih/formula/9e10e1c43b86a8cd4360ca9b57232164.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/02b9693718209737a601ebcebb871f8d.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，故</span><span style=\"font-family: 'Times New Roman';\">③</span><span style=\"font-family: 宋体;\">正确；</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∵对称轴是直线</span><img src=\"https://img.xkw.com/dksih/formula/9b384412acba251d87902ab928902f16.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，抛物线开口向下，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴当</span><img src=\"https://img.xkw.com/dksih/formula/9b384412acba251d87902ab928902f16.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">时，函数取得最大值，为</span><img src=\"https://img.xkw.com/dksih/formula/478ce8fd7d94c89d630b8bb9a2fbf6a8.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">殷伟对于任意实数</span><span style=\"font-style: italic;font-family: 'Times New Roman';\">m</span><span style=\"font-family: 宋体;\">，都有</span><img src=\"https://img.xkw.com/dksih/formula/a4b158f88b2996328ef059d13fba41bf.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/ebe9eedf4346c102cdfcd993eb7fcd34.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">∴</span><img src=\"https://img.xkw.com/dksih/formula/72c97173423a3351792c8cf77c4bf004.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">即</span><img src=\"https://img.xkw.com/dksih/formula/cca2280d5979dc8f7118ca2b9d525fa8.svg\" class=\"xkw-math-img\"><span style=\"font-family: 宋体;\">，故</span><span style=\"font-family: 'Times New Roman';\">④</span><span style=\"font-family: 宋体;\">错误；</span></p><p style=\"text-align: left;\"><span style=\"font-family: 宋体;\">故选：</span><span style=\"font-family: 'Times New Roman';\">C</span></p>"
  } ]
}

