source.formattedExplanation:
{
  "explanationSegs" : [ {
    "name" : "导语",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">这篇文言文节选自《资治通鉴》，描写曹操与袁绍在军事斗争中的战略较量。文中，袁绍因骄傲自满，未听从部下建议，导致失败；反观曹操，采纳许攸的计策，巧妙用兵，最终取得胜利。文章通过人物对话和行动，生动展现曹操的果断与机智，以及袁绍的优柔和自大。故事情节紧凑，从一个侧面反映了三国时期复杂多变的政治军事斗争。</span></p>"
  }, {
    "name" : "(1)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生正确理解文言实词的意义和用法的能力。</span></p><p left;\"="" style='\"text-align:'><span 'times="" new="" roman';\"="" style='\"font-family:'>A.</span><span style='\"font-family:' 宋体;\"="">正确。句意：必能捉住曹操。</span></p><p left;\"="" style='\"text-align:'><span 'times="" new="" roman';\"="" style='\"font-family:'>B.</span><span style='\"font-family:' 宋体;\"="">正确。句意：(等不及穿鞋)光着脚出来迎接他。</span></p><p left;\"="" style='\"text-align:'><span 'times="" new="" roman';\"="" style='\"font-family:'>C.</span><span style='\"font-family:' 宋体;\"="">正确。句意：我的大事可成功了！</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>D.</span><span style='\"font-family:' 宋体;\"="">错误。“知”，同“智”，智慧。句意：我的智谋与力量都已衰竭。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">故选</span><span 'times="" new="" roman';\"="" style='\"font-family:'>D</span><span style='\"font-family:' 宋体;\"="">。</span></p>"
  }, {
    "name" : "(2)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生正确理解文言虚词的意义和用法及一词多义的能力。</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>A.</span><span style='\"font-family:' 宋体;\"="">不同。用/来。句意：却派重兵进攻曹军大营。/撰写《师说》一文来赠给他。</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>B.</span><span style='\"font-family:' 宋体;\"="">相同。都是“向”。句意：就又去袁绍那里诬告张郃。/却以向老师学习为耻。</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>C.</span><span style='\"font-family:' 宋体;\"="">相同。都是“竟然”。句意：不料今天竟然抓住了你。/现在他们（君子）的见识竟然反而比不上（巫医乐师百工之人）。</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>D</span><span style='\"font-family:' 宋体;\"="">.相同。都是主谓之间，取消句子独立性。句意：在袁绍强盛的时候。/从师学习的风尚不流传。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">故选</span><span 'times="" new="" roman';\"="" style='\"font-family:'>A</span><span style='\"font-family:' 宋体;\"="">。</span></p>"
  }, {
    "name" : "(3)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生文言文断句的能力。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">句意：曹操营寨坚固，一定不能攻克。如果淳于琼等被捉，我们都将成为俘虏了。</span></p><p left;\"="" style='\"text-align:'><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 宋体;\"="">曹公营”名词，作主语；“固”，作谓语。所以在“固”后断开，排除</span><span 'times="" new="" roman';\"="" style='\"font-family:'>AC</span><span style='\"font-family:' 宋体;\"="">。</span></p><p left;\"="" style='\"text-align:'><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 宋体;\"="">攻”是动词，作谓语；“之”是代词，作宾语；“必不拔”是结果；“若”表假设，放在句首。“琼等”作主语；“见禽”是被动结构，作谓语。所以在“拔”后断开，在“禽”后断开，排除</span><span 'times="" new="" roman';\"="" style='\"font-family:'>D</span><span style='\"font-family:' 宋体;\"="">。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">故选</span><span 'times="" new="" roman';\"="" style='\"font-family:'>B</span><span style='\"font-family:' 宋体;\"="">。</span></p>"
  }, {
    "name" : "(4)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生正确把握文学常识的能力。</span></p><p style='\"text-align:justify;word-break:break-word;\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>C.</span><span style='\"font-family:' 宋体;\"="">“自称‘孤’，看出他有当皇帝的野心”错误，东周以前，“孤”是王的自称，而“寡人”也是王和诸侯王的自称谦词。秦汉时期，秦始皇统一六国后，开始使用“朕”作为皇帝的自称，而“孤”的使用相对减少。东汉末年及三国时期，群雄割据，一些割据一方的首领也自称为“孤”。隋唐时期，唐朝的皇帝在特定语境下也会使用“孤”作为自称。</span></p><p left;\"="" style='\"text-align:'><span style='\"font-family:' 宋体;\"="">故选</span><span 'times="" new="" roman';\"="" style='\"font-family:'>C</span><span style='\"font-family:' 宋体;\"="">。</span></p>"
  }, {
    "name" : "(5)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生理解文章内容的能力。</span></p><p style='\"\"'><span 'times="" new="" roman';\"="" style='\"font-family:'>C.</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 宋体;\"="">许攸、张郃因自己的建议不被采纳所以背叛袁绍投奔曹操”错误，许攸主要是因为“会攸家犯法，审配收系之，攸怒”，然后降操的。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">故选</span><span 'times="" new="" roman';\"="" style='\"font-family:'>C</span><span style='\"font-family:' 宋体;\"="">。</span></p>"
  }, {
    "name" : "(6)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生翻译文言文句子的能力。</span></p><p left;\"="" style='\"text-align:'><span style='\"font-family:' 宋体;\"="">（1）“公”敬称，您；“外”，名词作状语，在外；“……也”表判断。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">（2）“将”率领；“夜”，名词作状语，在夜晚；“间”，偏僻的小路。</span></p>"
  }, {
    "name" : "(7)题详解",
    "html" : "<p style='\"\"'><span style='\"font-family:' 宋体;\"="">本题考查学生分析理解文章内容的能力。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">①“跣出迎之”，曹操听说许攸来投奔，来不及穿鞋就出去迎接，这充分体现了曹操对贤才的急切渴望，《短歌行》中“周公吐哺”相呼应。周公为了接待贤士，“一沐三握发，一饭三吐哺”，曹操“跣出迎之”的行为就如同周公一样，展现出他渴望天下贤才都来归附自己，以实现统一天下的抱负。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">②③句曹操俘获沮授后，“遂赦而厚遇焉”，对他以礼相待，这可以看做是“呦呦鹿鸣，食野之苹”的注解。表明麋鹿找到了艾蒿，就会相呼相鸣。意思是说只要宾客到这里来，就一定会待以“嘉宾”之礼，欢快融洽地相处并合作。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">④《短歌行》里曹操希望有大量人才来为自己所用。在诗歌中借用多个典故“青青子衿，悠悠我心”“呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙”“周公吐哺，天下归心”，来表达自己求贤若渴的思想。选文中曹操对待谋臣策士的作法正是这种思想的体现。</span></p><p style='\"\"'><span style='\"font-family:' 宋体;\"="">参考译文：</span></p><p 28px;\"="" style='\"text-indent:'><span style='\"font-family:' 楷体;\"="">冬季，十月，袁绍又派大批车辆运粮草，让大将淳于琼等率领一万多人护送，停留在袁绍大营以北四十里处。沮授劝袁绍说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">可派遣蒋奇另外率一支军队，驻扎在运粮队的外围，以防曹操派军袭击。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">袁绍不听。许攸说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">曹操兵少，而集中全力来抵抗我军，许都由剩下的人守卫，防备一定空虚。如果派一支队伍轻装前进，连夜奔袭，或许可以攻陷许都。占领许都后，就奉迎天子来讨伐曹操，必能捉住曹操。袁绍不同意，说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">我一定要先捉住曹操。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">正在这时，许攸家里有人犯法，留守邺城的审配将他们逮捕，许攸知道后大怒，就投奔了曹操。曹操听说许攸前来，(等不及穿鞋)光着脚出来迎接他，拍手笑着说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">子卿你远道而来，我的大事可成功了！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">入座以后，许攸对曹操说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">袁军势大，你有什么办法对付他？现在还有多少粮草？</span><span style='\"font-family:' 宋体;\"="">”“</span><span style='\"font-family:' 楷体;\"="">曹操说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">还可以支持一年。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">许攸说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">没有那么多，再说一次！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">曹操又说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">可以支持半年。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">许攸说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">您不想击破袁绍吗！为什么不说实话呢！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">曹操说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">刚才只是开玩笑罢了。其实只可应付一个月，怎么办呢？</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">许攸说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">您孤军独守，外无救援而粮草已尽，这是危急的关头。袁绍有一万多辆辎重车，在乌巢，守军戒备不严密，如果派轻装部队袭击，出其不意而到，焚毁他们的粮草与军用物资，不出三天，袁绍大军就会自行溃散。</span><span style='\"font-family:' 宋体;\"="">”</span></p><p 28px;\"="" left;text-indent:="" style='\"text-align:'><span style='\"font-family:' 楷体;\"="">曹操大喜，于是留下曹洪、荀攸防守大营，亲自率领步兵骑兵五千人出击，军队一律用袁军的旗号，夜里从小道出营。到达乌巢后，围住袁军辎重，四面放火，袁军营中大乱。袁绍听到曹操袭击淳于琼的消息，对儿子袁谭说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">即使曹操攻破淳于琼，我去攻破他的大营，他一定无处可归了！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">于是派遣大将高览、张郃等人去攻打曹军大营。张郃说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">曹操亲率精兵前去袭击，必能攻破淳于琼等，他们一败，那么大势已去，请先去救援淳于琼。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">郭图坚持要先攻曹操营寨。张郃说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">曹操营寨坚固，一定不能攻克。如果淳于琼等被捉，我们都将成为俘虏了。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">袁绍只是派轻骑兵去援救淳于琼，却派重兵进攻曹军大营，未能攻下。郭图因自己的计策失败，心中羞愧，就又去袁绍那里诬告张郃，说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">张郃听说我军失利，幸灾乐祸。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">张郃听说后，又恨又怕，就与高览烧毁了攻营的器械，到曹营去投降。曹洪生怕中计，不敢接受他们投降，荀攸说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">张郃因为计策不被袁绍采用，一怒之下来投奔，您有什么可怀疑的！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">于是接受张郃、高览的投降，于是袁军惊恐，全面溃败。曹操追赶不及，但缴获了袁绍的全部辎重、图书和珍宝。沮授没有赶上袁绍渡河，被曹操的军队抓住。曹操与沮授有旧交，便迎接他并说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">我们两人所属的阵营，完全不一样，于是就被隔开断绝了联系，不料今天竟然抓住了你！</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">沮授回答说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">袁绍战略失误，自取败亡。我的智谋与力量都已衰竭，被擒是理所当然的。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">曹操说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">袁绍没有谋略，不采纳你的计策，如今天下大乱尚未平定，正应当与你一同谋划如何平定战乱。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">沮授说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">我的叔父和亲弟弟，命悬在袁绍手中，如果承受到您的神灵保佑，让我马上死了才是福气。</span><span style='\"font-family:' 宋体;\"="">”</span></p><p 28px;\"="" left;text-indent:="" style='\"text-align:'><span style='\"font-family:' 楷体;\"="">曹操叹息说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">如果我早点得到你，天下的事都不足发愁了。</span><span style='\"font-family:' 宋体;\"="">”</span><span style='\"font-family:' 楷体;\"="">于是赦免了沮授并且给予优厚待遇。沮授不久后策划回归袁氏，曹操便杀了他。曹操在收集袁绍的信件时，发现了许昌及军中人写给袁绍的信，便全部烧掉了，说：</span><span style='\"font-family:' 宋体;\"="">“</span><span style='\"font-family:' 楷体;\"="">在袁绍强盛的时候，我都不能自保，何况众人呢！</span><span style='\"font-family:' 宋体;\"="">”</span></p>"
  } ]
}

